// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address caller) public {
        amount = bound(amount, 0, 1 ether);
        vm.assume(caller != address(this));

        if (amount > 0) {
            vm.deal(address(this), amount);
            (bool s, ) = address(c).call{value: amount}("");
            require(s);
        }

        uint256 balanceBefore = address(c).balance;

        vm.deal(caller, 1 wei);
        vm.prank(caller);
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = address(c).balance;

        assertTrue(balanceAfter >= balanceBefore);
    }
}
